def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0
        if no_water >= 2 or hp <= 4:
            base = 42.0
        elif supply <= 17:
            base = 28.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    strong_pressure = 0
    weak_or_broke = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                b = float(bid)
                prev_bids.append(b)
                if b >= 70:
                    strong_pressure += 1
                if b <= 5:
                    weak_or_broke += 1
            except Exception:
                pass
        if float(opp.get('budget', 0)) < 25:
            weak_or_broke += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0
    if no_water >= 2 or hp <= 3:
        urgency = 3
    elif no_water == 1 or hp <= 6:
        urgency = 2
    elif hp <= 8:
        urgency = 1

    reserve_target = max(0.0, (10 - day) * 8.0)
    spendable = max(0.0, budget - reserve_target)

    if urgency == 3:
        target = max(62.0, highest_prev + 3.0)
        if supply <= 17:
            target = max(target, 78.0)
        return float(max(0.0, min(budget, target)))

    if urgency == 2:
        target = 34.0 + 18.0 * scarcity
        if highest_prev > 0:
            target = max(target, min(highest_prev + 1.5, 72.0))
        if strong_pressure >= 2 and supply <= 18:
            target = max(target, 58.0)
        return float(max(0.0, min(budget, target)))

    target = 16.0 + 12.0 * scarcity
    if weak_or_broke >= len(alive):
        target = min(target, 14.0)
    elif highest_prev >= 75.0:
        target = min(target, 18.0)
    elif highest_prev >= 45.0:
        target = max(target, avg_prev * 0.55)
    else:
        target = max(target, avg_prev * 0.8 if avg_prev > 0 else target)

    if supply <= 16:
        target += 6.0
    elif supply >= 23:
        target -= 3.0

    if spendable < target and urgency == 0:
        target = min(target, max(10.0, spendable * 0.7))

    target = max(0.0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents are alive, conserve budget.
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday behavior (immediate reaction only)
    prev_bids = []
    prev_hp = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', None) or {}
        if pt and pt.get('bid') is not None:
            try:
                prev_bids.append(float(pt['bid']))
            except Exception:
                pass
        # also capture yesterday hp_after to infer aggressiveness/pressure
        if pt and pt.get('hp_after') is not None:
            try:
                prev_hp.append(float(pt['hp_after']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: if supply is closer to MIN_SUPPLY, competition is tighter.
    # Normalize to [0,1] where 0 => MIN_SUPPLY, 1 => MAX_SUPPLY
    try:
        t = (float(supply) - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    except Exception:
        t = 0.5
    t = max(0.0, min(1.0, t))
    tightness = 1.0 - t

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Base bid target: aim around a fraction of DAILY_SALARY.
    # If tightness is high, increase.
    base = DAILY_SALARY * (0.52 + 0.18 * tightness)

    # If opponents bid aggressively yesterday, counter with a slight overbid.
    # But cap by what we can afford.
    bid = base

    # Cindy died with 0 bid; ignore if present, but if others still bid high, respond.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure: bid near high but not maximal.
        if my_hp > 4:
            bid = max(bid, min(my_budget, highest_prev_bid * 0.92 + 2.0))
        else:
            bid = max(bid, min(my_budget, highest_prev_bid * 1.00 + 4.0))
    elif highest_prev_bid > 0:
        # Moderate competition: bid around avg or slightly above.
        target = max(base, avg_prev_bid * (0.85 + 0.1 * (1.0 - tightness)))
        bid = max(bid, target)

    # Survival safeguard: if my HP is critical, spend more to secure water.
    if my_hp <= 2.0:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif my_hp <= 4.0:
        bid = max(bid, DAILY_SALARY * 0.75)

    # Budget cap
    if my_budget <= 0.0:
        return 0.0

    bid = min(bid, my_budget)

    # If supply is very low (near MIN_SUPPLY), slightly increase to avoid being priced out.
    if float(supply) <= float(MIN_SUPPLY) + 0.5:
        bid = min(my_budget, bid * 1.08)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

